package org.schoolkernel.workspace;

import static org.junit.jupiter.api.Assertions.*;
import java.util.List;
import com.microsoft.playwright.APIResponse;
import com.microsoft.playwright.options.RequestOptions;
import org.junit.jupiter.api.Test;
import tools.jackson.databind.JsonNode;
import tools.jackson.databind.node.ObjectNode;

/** UC-8 atomic operations, inherited settings and stable identities through the real boundary. */
class DefinitionRequirementsBrowserIT extends WorkbenchBrowserSupport {
    @Test
    void browserNewRequirementAllSharedFieldsCountChangesCancelAndRestart() {
        initial(false);open();requirements();JsonNode source=draft().path("sourceDocument").deepCopy(),ungrouped=definition().path("lessons").get(1).deepCopy();
        page().locator("#add-requirement").click();page().locator("#requirement-cohortId-picker").fill("Year 7A");page().locator("#requirement-cohortId-options button").first().click();page().locator("#requirement-subjectId-picker").fill("Science");page().locator("#requirement-subjectId-options button").first().click();assertEquals("year-7a-science",page().locator("#requirement-seriesId").inputValue());page().locator("#requirement-seriesId").fill("Series.ID_9");count("2");
        value("teacherId","teacher-alex");value("requiredRoomCapabilityIds","lab, Extra.Token_9");value("preferredRoomIds","room-101");value("undesirablePeriodIds","mon-3");value("periodLock","mon-1");value("roomLock","room-101");
        String before=storedDocument();preview();workbench.awaitText("Fresh additions");page().locator("#cancel-requirement-review").click();assertEquals(before,storedDocument());assertEquals("2",page().locator("#requirement-count").inputValue());save();
        JsonNode generated=series("Series.ID_9");assertEquals(2,generated.size());for(int i=0;i<2;i++){JsonNode row=generated.get(i);assertEquals("Series.ID_9.0"+(i+1),row.path("id").asString());assertEquals("Year 7A Science "+(i+1),row.path("displayName").asString());assertEquals(11,row.size());assertEquals("teacher-alex",row.path("teacherId").asString());assertEquals("mon-1",row.path("periodLock").asString());assertEquals("room-101",row.path("roomLock").asString());assertEquals(JSON.readTree("[\"lab\",\"Extra.Token_9\"]"),row.path("requiredRoomCapabilityIds"));}
        assertEquals("mon-1",draft().path("editingContext").path("authoredLocks").path("Series.ID_9.01").path("periodLock").asString());assertTrue(draft().path("issues").toString().contains("Persistent locked collision"));assertTrue(draft().path("issues").toString().contains("required room capabilities"));assertEquals(source,draft().path("sourceDocument"));assertEquals(ungrouped,definition().path("lessons").get(1));
        count("1");before=storedDocument();page().locator("#preview-requirement").click();workbench.awaitText("Select exactly 1 occurrences");assertEquals(before,storedDocument());page().getByRole(com.microsoft.playwright.options.AriaRole.CHECKBOX,new com.microsoft.playwright.Page.GetByRoleOptions().setName("Cancel occurrence: Year 7A Science 1 (Series.ID_9.01)").setExact(true)).check();save();assertEquals("Series.ID_9.02",series("Series.ID_9").get(0).path("id").asString());
        count("2");page().getByRole(com.microsoft.playwright.options.AriaRole.CHECKBOX,new com.microsoft.playwright.Page.GetByRoleOptions().setName("Cancel occurrence: Year 7A Science 2 (Series.ID_9.02)").setExact(true)).uncheck();save();generated=series("Series.ID_9");assertEquals("Series.ID_9.02",generated.get(0).path("id").asString());assertEquals("Series.ID_9.03",generated.get(1).path("id").asString());assertTrue(draft().path("removedIdentities").toString().contains("Series.ID_9.01"));
        String saved=storedDocument();workbench.reload();requirements();assertEquals(saved,storedDocument());try(var restarted=startRestartableWorkspace()){int p=((org.springframework.boot.web.server.context.WebServerApplicationContext)restarted).getWebServer().getPort();workbench.open(p);requirements();assertEquals(saved,storedDocument());assertEquals(3,context("Series.ID_9").path("nextSequence").intValue()-1);}
    }

    @Test
    void importedMixedValuesRequireSelectedFollowersAndEqualExceptionIntentPersists() {
        initial(true);open();requirements();workbench.awaitText("Mixed — imported values disagree");JsonNode nativeBefore=definition().deepCopy();ObjectNode operation=operation("series-math-7a",2);change(operation,"teacherId","teacher-alex");
        String before=storedDocument();assertEquals(409,previewCommand(operation("series-math-7a",3)).status());assertEquals(before,storedDocument());assertEquals(409,previewCommand(operation).status());assertEquals(before,storedDocument());operation.withObject("followers").putArray("teacherId").add("lesson-math-1");assertEquals(200,saveCommand(operation).status());
        assertEquals("teacher-alex",lesson("lesson-math-1").path("teacherId").asString());assertEquals("teacher-blair",lesson("imported.math.2").path("teacherId").asString());assertTrue(context("series-math-7a").path("exceptions").path("imported.math.2").toString().contains("teacherId"));
        operation=operation("series-math-7a",2);change(operation,"teacherId","teacher-blair");assertEquals(200,saveCommand(operation).status());assertEquals("teacher-blair",lesson("lesson-math-1").path("teacherId").asString());assertEquals("teacher-blair",lesson("imported.math.2").path("teacherId").asString());assertTrue(context("series-math-7a").path("exceptions").path("imported.math.2").toString().contains("teacherId"));
        operation=operation("series-math-7a",3);change(operation,"teacherId","teacher-alex");JsonNode preview=JSON.readTree(previewCommand(operation).text());assertTrue(preview.path("overwrittenExceptions").isEmpty());assertEquals(200,saveCommand(operation).status());assertEquals("teacher-alex",lesson("lesson-math-1").path("teacherId").asString());assertEquals("teacher-blair",lesson("imported.math.2").path("teacherId").asString());assertEquals("teacher-alex",series("series-math-7a").get(2).path("teacherId").asString());
        operation=operation("series-math-7a",3);change(operation,"teacherId","teacher-blair");operation.withArray("applyToAllFields").add("teacherId");preview=JSON.readTree(previewCommand(operation).text());assertEquals(1,preview.path("overwrittenExceptions").size());assertEquals("imported.math.2",preview.path("overwrittenExceptions").get(0).path("lessonId").asString());assertEquals(200,saveCommand(operation).status());for(JsonNode row:series("series-math-7a"))assertEquals("teacher-blair",row.path("teacherId").asString());assertFalse(context("series-math-7a").path("exceptions").path("imported.math.2").toString().contains("teacherId"));
        for(JsonNode row:nativeBefore.path("lessons")){assertEquals(row.path("id"),lesson(row.path("id").asString()).path("id"));assertEquals(row.path("displayName"),lesson(row.path("id").asString()).path("displayName"));}assertEquals(nativeBefore.path("lessons").get(1),definition().path("lessons").get(1));String saved=storedDocument();workbench.reload();requirements();assertEquals(saved,storedDocument());
    }

    @Test
    void incompleteCountsZeroContextAndSupportedInvalidDefaultsRemainDurable() {
        initial(false);open();requirements();JsonNode occurrences=definition().path("lessons").deepCopy();ObjectNode operation=operation("series-math-7a",1);operation.put("count","not a number");change(operation,"teacherId","unknown");assertEquals(200,saveCommand(operation).status());assertEquals(occurrences,definition().path("lessons"));assertEquals("not a number",context("series-math-7a").path("count").asString());assertTrue(draft().path("issues").toString().contains("nonnegative integer weekly count"));
        operation=operation("series-math-7a",1);assertEquals(200,saveCommand(operation).status());assertEquals("unknown",lesson("lesson-math-1").path("teacherId").asString());assertTrue(draft().path("issues").toString().contains("teacherId"));
        ObjectNode teacher=JSON.createObjectNode().put("id","unknown").put("displayName","Explicit new teacher");teacher.putArray("qualifiedSubjectIds").add("math");ObjectNode add=JSON.createObjectNode().put("originalId","");add.set("item",teacher);assertEquals(200,post("/api/definition-draft/teachers",add,null).status());assertFalse(draft().path("issues").toString().contains("BLOCKING"));
        operation=operation("series-math-7a",0);operation.withArray("removeIds").add("lesson-math-1");change(operation,"teacherId","teacher-alex");assertEquals(200,saveCommand(operation).status());assertTrue(series("series-math-7a").isEmpty());assertEquals(0,context("series-math-7a").path("count").intValue());assertFalse(draft().path("issues").toString().contains("Requirement"));
        operation=operation("series-math-7a",0);operation.put("cohortId","missing");operation.withObject("changes").putObject("requiredRoomCapabilityIds").put("mode","value").put("value",false);assertEquals(200,saveCommand(operation).status());assertTrue(draft().path("issues").toString().contains("Requirement"));assertFalse(context("series-math-7a").path("defaults").path("requiredRoomCapabilityIds").booleanValue());assertTrue(series("series-math-7a").isEmpty());
    }

    @Test
    void staleCancelledStateIdentityCsrfStorageTransportAndResponsiveNoPartialWrites() throws Exception {
        storeAccepted(fixtures.validAcceptedDocument());workbench.open();open();requirements();JsonNode source=draft().path("sourceDocument").deepCopy();ObjectNode operation=operation("series-math-7a",2);JsonNode preview=JSON.readTree(previewCommand(operation).text());assertEquals(1,preview.path("sourcePlacements").size());String before=storedDocument();ObjectNode other=operation("series-math-7a",1);change(other,"teacherId","teacher-alex");assertEquals(200,saveCommand(other).status());String newer=storedDocument();assertEquals(409,post("/api/definition-draft/requirements",JSON.createObjectNode().set("request",operation).put("token",preview.path("token").asString()),null).status());assertEquals(newer,storedDocument());
        workbench.reload();requirements();count("2");for(int width:List.of(1600,1280,390,700)){workbench.viewport(width,844);workbench.expect("document.documentElement.scrollWidth <= innerWidth");assertEquals(newer,storedDocument());if(width<=700)assertEquals(0,page().locator("#requirement-form").count());}workbench.viewport(1280,800);assertEquals("2",page().locator("#requirement-count").inputValue());nav("Review");page().locator("#school-stay").click();nav("Review");page().locator("#school-discard-working").click();requirements();assertEquals(newer,storedDocument());
        count("2");withRejectedWorkspaceUpdates("NEW.lifecycle_state = 'DEFINITION_DRAFT'",()->{preview();page().locator("#save-requirement").click();workbench.awaitText("No change was committed");assertEquals(newer,storedDocument());assertEquals("2",page().locator("#requirement-count").inputValue());});
        page().route("**/api/definition-draft/requirements",route->route.abort());preview();page().locator("#save-requirement").click();workbench.awaitText("No change was committed");assertEquals(newer,storedDocument());page().unroute("**/api/definition-draft/requirements");save();assertEquals(source,draft().path("sourceDocument"));for(var e:source.properties())assertEquals(e.getValue(),storedWorkspaceDocument().path(e.getKey()));
        ObjectNode collision=operation("series-math-7a",2).put("originalSeriesId","");before=storedDocument();assertEquals(409,previewCommand(collision).status());assertEquals(before,storedDocument());ObjectNode immutable=operation("series-math-7a",2).put("seriesId","changed");assertEquals(409,previewCommand(immutable).status());assertEquals(before,storedDocument());
        operation=operation("BAD ID",0);before=storedDocument();assertEquals(409,previewCommand(operation).status());assertEquals(before,storedDocument());APIResponse csrf=page().request().post(base()+"/api/definition-draft/requirements/preview",RequestOptions.create().setData(JSON.writeValueAsString(operation)).setHeader("Content-Type","application/json").setHeader("Origin",base()).setHeader("If-Match","\"ws-"+storedVersion()+"\""));assertEquals(403,csrf.status());assertEquals(before,storedDocument());
        for(WorkspaceState state:WorkspaceState.values()){if(state==WorkspaceState.DEFINITION_DRAFT)continue;store(state.name(),storedWorkspaceDocument());before=storedDocument();assertEquals(409,previewCommand(operation("series-math-7a",1)).status());assertEquals(before,storedDocument());}
    }

    private void initial(boolean mixed){ObjectNode def=((ObjectNode)fixtures.validAcceptedDocument().path("acceptedBaseline").path("definition")).deepCopy();if(mixed){def.withArray("teachers").addObject().put("id","teacher-blair").put("displayName","Blair").putArray("qualifiedSubjectIds").add("math");ObjectNode row=((ObjectNode)def.path("lessons").get(0)).deepCopy().put("id","imported.math.2").put("displayName","Keep imported name").put("teacherId","teacher-blair");def.withArray("lessons").add(row);}ObjectNode doc=JSON.createObjectNode();doc.set("initialDefinition",def);store("INITIAL_DRAFT",doc);workbench.open();}
    private com.microsoft.playwright.Page page(){return workbench.page();}
    private void open(){page().locator("#open-authoring").click();page().locator("#confirm-authoring").click();workbench.awaitText("Saved school-definition draft");}
    private void nav(String section){page().locator("button[data-section='"+section+"']").click();}
    private void expandForm() {
        var groups = workbench.page().locator("#requirement-form details");
        for (int i = 0; i < groups.count(); i++) if (groups.nth(i).getAttribute("open") == null) groups.nth(i).locator(":scope > summary").click();
    }
    private void requirements(){nav("Weekly requirements");page().locator("#requirement-form").waitFor(); expandForm(); }
    private void count(String value){page().locator("#requirement-count").fill(value);}
    private void value(String field,String value){ expandForm(); page().locator("#requirement-"+field+"-mode").selectOption("value");expandForm();page().locator("#requirement-"+field).fill(value);}
    private void preview(){page().locator("#preview-requirement").click();page().locator("#requirement-preview").waitFor();}
    private void save(){long version=storedVersion();preview();page().locator("#save-requirement").click();workbench.expect("document.querySelector('#school-save-status')?.textContent.startsWith('Saved —')");assertEquals(version+1,storedVersion());page().locator("#requirement-form").waitFor();}
    private JsonNode draft(){return storedWorkspaceDocument().path("definitionDraft");}
    private JsonNode definition(){return draft().path("definition");}
    private JsonNode context(String id){return draft().path("editingContext").path("requirements").path(id);}
    private JsonNode lesson(String id){for(JsonNode row:definition().path("lessons"))if(id.equals(row.path("id").asString()))return row;fail("Missing occurrence "+id);return null;}
    private JsonNode series(String id){var rows=JSON.createArrayNode();for(JsonNode row:definition().path("lessons"))if(id.equals(row.path("seriesId").asString("")))rows.add(row);return rows;}
    private ObjectNode operation(String id,int count){ObjectNode r=JSON.createObjectNode().put("originalSeriesId",id).put("seriesId",id).put("cohortId","cohort-7a").put("subjectId","math").put("count",count);r.putObject("changes");r.putObject("followers");r.putArray("applyToAllFields");r.putArray("removeIds");return r;}
    private void change(ObjectNode r,String field,String value){r.withObject("changes").putObject(field).put("mode","value").put("value",value);}
    private String base(){return "http://localhost:"+port;}
    private APIResponse previewCommand(JsonNode operation){return post("/api/definition-draft/requirements/preview",operation,null);}
    private APIResponse saveCommand(JsonNode operation){APIResponse preview=previewCommand(operation);assertEquals(200,preview.status(),preview.text());JsonNode p=JSON.readTree(preview.text());ObjectNode envelope=JSON.createObjectNode().put("token",p.path("token").asString());envelope.set("request",operation);return post("/api/definition-draft/requirements",envelope,null);}
    private APIResponse post(String path,JsonNode body,String version){JsonNode csrf=JSON.readTree(page().request().get(base()+"/api/csrf").text());return page().request().post(base()+path,RequestOptions.create().setData(JSON.writeValueAsString(body)).setHeader("Content-Type","application/json").setHeader("Origin",base()).setHeader("If-Match",version==null?"\"ws-"+storedVersion()+"\"":version).setHeader(csrf.path("headerName").asString(),csrf.path("token").asString()));}
    private void store(String state,JsonNode document){jdbc.sql("UPDATE workspace_aggregate SET lifecycle_state=:state, version=version+1, active_run_id=NULL, document=CAST(:document AS jsonb) WHERE workspace_id=1").param("state",state).param("document",JSON.writeValueAsString(document)).update();}
}
